import * as React from "react"
import { adminCall } from "./admin-call"
import * as s from "./PipelineConsole.module.css"

/**
 * Admin → Launch console — FCS-123.
 * ============================================================================
 * The whole customer journey, one step at a time, with a log for every step, in one place. Cheapest first: a free link, a subdomain, a
 * subdomain after paying through Stripe, a domain somebody owns, and last the one thing that costs real money, buying a domain.
 *
 * For every step it shows TWO things side by side: what the run's own record says, and what is really true right now (it looks at GitHub,
 * Cloudflare, Stripe and the database). When they disagree that is shown as DRIFT, so "has it run, has it stalled, is it still there" is
 * never a guess. Any step can be run on its own, or the run can carry on from any step. Nothing that spends money runs unless the exact
 * confirmation is typed, and a REHEARSAL cannot spend money at all (the rules are in the function, not here: skipping this screen meets
 * the same rules).
 *
 * Everything it says about a step comes from the server (admin-pipeline); this file decides nothing about money or order.
 */

const api = body => adminCall("admin-pipeline", body)

const STATUS_WORD = { todo: "Not done", running: "Running…", done: "Done", failed: "Failed", pending: "Waiting", skipped: "Skipped" }
const WORLD_WORD = { done: "True right now", todo: "Not there yet", blocked: "Blocked", unknown: "Could not check" }
const COST_WORD = { free: "Free", stripe: "Stripe", money: "REAL MONEY" }
const LEVEL_MARK = { info: "·", ok: "✓", warn: "…", error: "✗", note: "✎", money: "$" }

const PLACEHOLDER = { path: "their-name", subdomain: "their-name", "paid-subdomain": "their-name", connect: "acme.com", buy: "homeservices.wiki" }

const when = iso => (iso ? new Date(iso).toLocaleString() : "")
const clock = iso => (iso ? new Date(iso).toLocaleTimeString() : "")

/** The text after "type exactly:" in a message from the server, for steps that ask for a confirmation by name. */
const phraseIn = text => {
  const m = /type exactly: (.+?)(?: and press Run\.)?$/.exec(String(text || ""))
  return m ? m[1].trim() : ""
}

function copy(text) {
  try {
    navigator.clipboard?.writeText(text)
  } catch {
    /* nothing to do: the text is on screen */
  }
}

const Mark = ({ ok }) => <span className={s.mark} data-ok={ok === true ? "yes" : ok === false ? "no" : "maybe"}>{ok === true ? "✓" : ok === false ? "✗" : "…"}</span>

/* ── what the server is set to ──────────────────────────────────────────── */

const SafetyBar = ({ safety }) => {
  if (!safety) return null
  const live = safety.stripe.mode === "live"
  return (
    <div className={s.safety} data-testid="safety">
      <span className={s.chip} data-tone={live ? "danger" : "safe"}>
        Stripe: {safety.stripe.mode === "none" ? "no key" : live ? "LIVE keys: real cards" : "TEST keys: no real money"}
      </span>
      <span className={s.chip} data-tone={safety.registrar.tokenConfigured ? "safe" : "warn"}>
        Domain registrar token: {safety.registrar.tokenConfigured ? "set" : "NOT set"}
      </span>
      <span className={s.chip} data-tone={safety.hostingMissing.length ? "warn" : "safe"}>
        {safety.hostingMissing.length ? `Hosting is missing: ${safety.hostingMissing.join(", ")}` : "Hosting tokens: set"}
      </span>
      {safety.stripe.unreadable ? <span className={s.chip} data-tone="danger">Stored Stripe keys cannot be read</span> : null}
      <span className={s.fine}>A rehearsal can never spend money. A real run asks, in words, before every step that does.</span>
    </div>
  )
}

/* ── starting a run ─────────────────────────────────────────────────────── */

const NewRun = ({ kinds, safety, testAccounts, onCreate, busy }) => {
  const [kind, setKind] = React.useState("path")
  const [target, setTarget] = React.useState("")
  const [mode, setMode] = React.useState("rehearsal")
  const [accountId, setAccountId] = React.useState("")
  const chosen = kinds.find(k => k.id === kind)
  const live = safety?.stripe.mode === "live"
  const spends = chosen && (chosen.cost === "money" || (chosen.cost === "stripe" && live))
  return (
    <form
      className={s.newRun}
      data-testid="new-run"
      onSubmit={event => {
        event.preventDefault()
        onCreate({ kind, target, mode, accountId })
      }}
    >
      <h2 className={s.h2}>Start a run</h2>
      <label className={s.label} htmlFor="pc-kind">What to test</label>
      <select id="pc-kind" className={s.input} value={kind} onChange={e => setKind(e.target.value)}>
        {kinds.map(k => (
          <option key={k.id} value={k.id}>
            {k.label} {k.cost === "money" ? "(real money)" : k.cost === "stripe" ? "(Stripe)" : "(free)"}
          </option>
        ))}
      </select>
      {chosen ? <p className={s.fine}>{chosen.summary}</p> : null}

      <label className={s.label} htmlFor="pc-target">{kind === "connect" || kind === "buy" ? "The domain" : "The name"}</label>
      <input id="pc-target" className={s.input} value={target} onChange={e => setTarget(e.target.value)} placeholder={PLACEHOLDER[kind]} autoComplete="off" spellCheck="false" />

      <fieldset className={s.modes}>
        <legend className={s.label}>How far may it go?</legend>
        <label className={s.mode} data-on={mode === "rehearsal" ? "yes" : undefined}>
          <input type="radio" name="pc-mode" checked={mode === "rehearsal"} onChange={() => setMode("rehearsal")} />
          <span><strong>Rehearsal</strong> Nothing can spend money. Steps that would are skipped, with the reason written down.</span>
        </label>
        <label className={s.mode} data-on={mode === "real" ? "yes" : undefined} data-danger={spends ? "yes" : undefined}>
          <input type="radio" name="pc-mode" checked={mode === "real"} onChange={() => setMode("real")} />
          <span><strong>Real</strong> Steps that spend money may run, but each one stops and asks you to type a confirmation first.</span>
        </label>
      </fieldset>
      {mode === "real" && spends ? (
        <p className={s.warn} data-testid="real-warning">
          {chosen.cost === "money"
            ? "A real registration is charged to the card on the Cloudflare account and is never refunded. Add the card first (see Quicklinks below)."
            : "Stripe is in LIVE mode: the checkout link takes a real payment."}
        </p>
      ) : null}

      {testAccounts.length ? (
        <>
          <label className={s.label} htmlFor="pc-account">Use an existing test account (optional)</label>
          <select id="pc-account" className={s.input} value={accountId} onChange={e => setAccountId(e.target.value)}>
            <option value="">Make a new one</option>
            {testAccounts.map(a => (
              <option key={a.id} value={a.id}>{a.email} ({a.plan})</option>
            ))}
          </select>
        </>
      ) : null}
      <button type="submit" className={s.button} disabled={busy || !target.trim()}>Start the run</button>
    </form>
  )
}

/* ── one step ───────────────────────────────────────────────────────────── */

const StepCard = ({ step, index, run, safety, act, busy }) => {
  const [confirm, setConfirm] = React.useState("")
  const rec = step.record
  const word = step.stalled ? "Stalled" : STATUS_WORD[rec.status] || rec.status
  const tone = step.stalled ? "stalled" : rec.status
  const live = safety?.stripe.mode === "live"
  // Once a costly step is DONE its confirmation box goes away, so there is nothing to type and nothing to press by accident: to run it
  // again it has to be reset first.
  const asked = step.phrase ? (rec.status === "done" ? "" : step.phrase) : phraseIn(rec.detail)
  const sub = rec.sub && rec.sub.length ? rec.sub : step.inspect.sub || []
  const open = ["failed", "pending", "running"].includes(rec.status) || step.stalled || step.drift
  // A step that needs a typed phrase stays locked once it is done (its box is gone, and what was typed must not keep it open).
  const locked = busy || !step.can.ok || (Boolean(step.phrase) && (rec.status === "done" || (run.mode === "real" && confirm.trim() !== step.phrase)))
  const run1 = () => act({ action: "step", id: run.id, step: step.id, confirm }, `Running “${step.label}”…`)
  const runFrom = () => act({ action: "from", id: run.id, step: step.id, confirm }, `Running from “${step.label}”…`)
  const data = run.data || {}

  return (
    <li className={s.step} data-status={tone} data-testid={`step-${step.id}`}>
      <div className={s.stepHead}>
        <span className={s.num}>{index + 1}</span>
        <h3 className={s.h3}>{step.label}</h3>
        <span className={s.cost} data-cost={step.cost} data-live={step.cost === "stripe" && live ? "yes" : undefined}>
          {COST_WORD[step.cost]}{step.cost === "stripe" && live ? ": REAL CARD" : ""}
        </span>
        <span className={s.pill} data-status={tone}>{word}</span>
      </div>
      <p className={s.explain}>{step.explain}</p>

      <p className={s.world} data-state={step.inspect.state}>
        <strong>In the real world:</strong> {WORLD_WORD[step.inspect.state] || step.inspect.state}. {step.inspect.detail}
      </p>
      {step.drift ? <p className={s.warn}>DRIFT: this run says it is done, but it is not true any more (somebody removed what it made). Run it again from here.</p> : null}
      {run.mode === "rehearsal" && step.rehearsalSkip ? <p className={s.fine}>In a rehearsal this step is skipped: it would {step.rehearsalSkip}.</p> : null}
      {rec.detail && rec.status !== "todo" ? (
        <p className={s.result} data-tone={rec.status}>
          {rec.finishedAt ? `${clock(rec.finishedAt)} · ` : ""}
          {rec.detail}
          {rec.attempts > 1 ? ` (attempt ${rec.attempts})` : ""}
        </p>
      ) : null}
      {step.stalled ? <p className={s.warn}>This step started {when(rec.startedAt)} and never finished. Press “Mark failed” to be able to run it again.</p> : null}

      {step.id === "payment" && data.checkoutUrl ? (
        <p className={s.callout}>
          <a href={data.checkoutUrl} target="_blank" rel="noreferrer">Open the Stripe checkout and pay ↗</a>
          {live ? " (LIVE: this takes a real card)" : " (test mode: use card 4242 4242 4242 4242, any future date, any CVC)"}
        </p>
      ) : null}
      {step.id === "zone" && Array.isArray(data.nameservers) && data.nameservers.length && rec.status !== "done" ? (
        <p className={s.callout}>Change the domain's nameservers, at its registrar, to: <strong>{data.nameservers.join(" and ")}</strong>. Then run this step again.</p>
      ) : null}
      {step.id === "wire" && Array.isArray(data.confirmRecords) && data.confirmRecords.length ? (
        <div className={s.callout}>
          These records already send visitors elsewhere and would be replaced (their email is not touched):
          <ul className={s.plain}>
            {data.confirmRecords.map(r => (
              <li key={`${r.type}-${r.name}-${r.content}`}><code>{r.type}</code> {r.name} → <code>{r.content}</code></li>
            ))}
          </ul>
        </div>
      ) : null}

      {sub.length ? (
        <details className={s.sub} open={open}>
          <summary>{sub.length} part{sub.length === 1 ? "" : "s"}, one by one</summary>
          <ul className={s.plain}>
            {sub.map((p, i) => (
              <li key={`${p.id || p.label}-${i}`}><Mark ok={p.ok} /> {p.label}{p.detail ? <span className={s.fine}> — {p.detail}</span> : null}</li>
            ))}
          </ul>
        </details>
      ) : null}

      {asked && run.status === "open" ? (
        <div className={s.confirm} data-testid={`confirm-${step.id}`}>
          <label className={s.label} htmlFor={`pc-confirm-${step.id}`}>
            {step.cost === "money" ? "This spends real money and cannot be undone. To allow it, type exactly:" : "To go ahead, type exactly:"}
          </label>
          <code className={s.phrase}>{asked}</code>
          <input id={`pc-confirm-${step.id}`} className={s.input} value={confirm} onChange={e => setConfirm(e.target.value)} autoComplete="off" spellCheck="false" />
        </div>
      ) : null}

      {run.status === "open" ? (
        <div className={s.actions}>
          <button type="button" className={s.button} disabled={locked} onClick={run1} title={step.can.ok ? "" : step.can.reason}>
            {step.manual ? "Check / make the link" : rec.status === "done" ? "Run again" : "Run this step"}
          </button>
          <button type="button" className={s.ghost} disabled={locked || step.destructive} onClick={runFrom} title={step.destructive ? "Tear-down is only ever run on its own" : ""}>
            Run from here on
          </button>
          {rec.status !== "todo" && !step.stalled ? (
            <button type="button" className={s.ghost} disabled={busy} onClick={() => act({ action: "reset", id: run.id, step: step.id }, "Resetting…")}>
              Reset from here
            </button>
          ) : null}
          {step.stalled ? (
            <button type="button" className={s.ghost} disabled={busy} onClick={() => act({ action: "unstick", id: run.id, step: step.id }, "Marking failed…")}>
              Mark failed
            </button>
          ) : null}
          {!step.can.ok ? <span className={s.fine}>{step.can.reason}</span> : null}
        </div>
      ) : null}
    </li>
  )
}

/* ── the log ────────────────────────────────────────────────────────────── */

const EventLog = ({ events, steps, run, act, busy }) => {
  const [only, setOnly] = React.useState("")
  const [note, setNote] = React.useState("")
  const shown = events.filter(e => !only || e.step === only)
  const label = id => steps.find(x => x.id === id)?.label || id
  const asText = () => shown.map(e => `${when(e.at)}  [${e.source}${e.step ? ` · ${e.step}` : ""}] ${e.level.toUpperCase()}  ${e.message}`).join("\n")
  return (
    <section className={s.log} data-testid="log">
      <div className={s.logHead}>
        <h2 className={s.h2}>Log</h2>
        <select className={s.input} aria-label="Show the log for" value={only} onChange={e => setOnly(e.target.value)}>
          <option value="">Every step</option>
          {steps.map(x => (
            <option key={x.id} value={x.id}>{x.label}</option>
          ))}
        </select>
        <button type="button" className={s.ghost} onClick={() => copy(asText())}>Copy as text</button>
      </div>
      <ol className={s.events}>
        {shown.length === 0 ? <li className={s.fine}>Nothing yet.</li> : null}
        {shown.map((e, i) => (
          <li key={`${e.at}-${e.id ?? i}`} className={s.event} data-level={e.level} data-source={e.source}>
            <span className={s.when}>{clock(e.at)}</span>
            <span className={s.src} data-source={e.source}>{e.source === "system" ? "System" : e.step ? label(e.step) : "Run"}</span>
            <span className={s.lvl}>{LEVEL_MARK[e.level] || "·"}</span>
            <span className={s.msg}>{e.message}</span>
          </li>
        ))}
      </ol>
      <form
        className={s.noteForm}
        onSubmit={event => {
          event.preventDefault()
          if (!note.trim()) return
          act({ action: "note", id: run.id, message: note, step: only || undefined }, "Adding the note…")
          setNote("")
        }}
      >
        <input className={s.input} value={note} onChange={e => setNote(e.target.value)} placeholder="Add a note to the log (what you saw, what you changed by hand)" aria-label="A note for the log" />
        <button type="submit" className={s.ghost} disabled={busy || !note.trim()}>Add note</button>
      </form>
      <p className={s.fine}>“System” lines are what the rest of the site recorded about this run's account (a payment arriving, an address being made).</p>
    </section>
  )
}

/* ── is it safe to spend? ───────────────────────────────────────────────── */

/* Asks the server to LOOK at everything the first real purchase depends on (reads only). A red line blocks the purchase step on the
   server too, so this is the same answer the Register button would get, shown before anybody types a phrase. */
const Readiness = ({ run }) => {
  const [r, setR] = React.useState(null)
  const [busy, setBusy] = React.useState(false)
  const [err, setErr] = React.useState("")
  const look = React.useCallback(async () => {
    setBusy(true)
    setErr("")
    const res = await api({ action: "readiness", id: run.id })
    setBusy(false)
    if (res.ok) setR(res.body)
    else setErr(res.body.message || "Could not check.")
  }, [run.id])
  React.useEffect(() => {
    look()
  }, [look])
  const bad = r ? r.items.filter(i => i.status === "fail" && i.blocks).length : 0
  const youCheck = r ? r.items.filter(i => i.status === "manual").length : 0
  return (
    <details className={s.panel} open data-testid="readiness" data-ready={r ? (r.ready ? "yes" : "no") : "unknown"}>
      <summary>
        Before real money moves: is everything in place?{" "}
        {r ? <span className={s.badge} data-mode={r.ready ? "rehearsal" : "real"}>{r.ready ? "READY" : `NOT READY: ${bad} to fix`}</span> : busy ? "Looking…" : ""}
      </summary>
      {err ? <p className={s.error} role="alert">{err}</p> : null}
      {r ? (
        <ul className={s.plain}>
          {r.items.map(i => (
            <li key={i.id} data-testid={`ready-${i.id}`} data-status={i.status}>
              {i.status === "manual" ? <span className={s.mark} data-ok="maybe">☐</span> : <Mark ok={i.status === "pass"} />} <strong>{i.label}</strong>
              {i.status === "manual" ? <span className={s.fine}> (you check this)</span> : null}
              <span className={s.fine}> — {i.detail}</span>
              {i.status !== "pass" && i.fix ? <span className={s.warn} style={{ display: "block" }}>{i.fix}</span> : null}
            </li>
          ))}
        </ul>
      ) : null}
      {r ? <p className={s.fine}>{r.ready ? "Everything the server can look at is in place." : "The purchase step will refuse until the red lines are fixed."} {youCheck} thing{youCheck === 1 ? "" : "s"} can only be checked by a person (the boxes). A mistake there is refused by Cloudflare and nothing is charged.</p> : null}
      <button type="button" className={s.ghost} disabled={busy} onClick={look}>{busy ? "Looking…" : "Check again"}</button>
    </details>
  )
}

/* ── one run ────────────────────────────────────────────────────────────── */

const RunView =({ view, safety, act, busy, reveal, clearReveal, notice, problem, refresh }) => {
  const { run, steps } = view
  const [shown, setShown] = React.useState(false)
  const done = steps.filter(x => ["done", "skipped"].includes(x.record.status)).length
  const pct = Math.round((done / steps.length) * 100)
  const next = steps.find(x => x.id === view.next)
  return (
    <div className={s.runView} data-testid="run-view">
      <div className={s.runHead}>
        <div>
          <h2 className={s.h2}>{run.kindLabel}: {run.target}</h2>
          <p className={s.fine}>
            Started {when(run.createdAt)} · <span className={s.badge} data-mode={run.mode}>{run.mode === "real" ? "REAL" : "REHEARSAL"}</span>{" "}
            <span className={s.badge} data-run={run.status}>{run.status === "open" ? "Open" : run.status === "finished" ? "Torn down" : "Abandoned"}</span>
            {" · "}
            <a href={run.address} target="_blank" rel="noreferrer">{run.address} ↗</a>
          </p>
        </div>
        <div className={s.actions}>
          <button type="button" className={s.ghost} disabled={busy} onClick={refresh}>Look again</button>
          {run.status === "open" ? (
            <button type="button" className={s.ghost} disabled={busy} onClick={() => window.confirm("Abandon this run? Nothing in the world is removed: tear it down first if there is something to clean up.") && act({ action: "abandon", id: run.id }, "Abandoning…")}>
              Abandon
            </button>
          ) : null}
        </div>
      </div>

      <div className={s.bar} role="img" aria-label={`${done} of ${steps.length} steps done`}><span style={{ width: `${pct}%` }} /></div>
      <p className={s.fine}>{done} of {steps.length} steps done{next ? ` · next: ${next.label}` : ""}</p>

      {busy ? <p className={s.working} role="status" data-testid="working">{busy}</p> : null}
      {problem ? <p className={s.error} role="alert">{problem}</p> : null}
      {notice ? <p className={s.notice} data-testid="notice">{notice}</p> : null}

      {reveal ? (
        <div className={s.reveal} data-testid="reveal">
          <strong>{reveal.label}</strong>
          <code>{shown ? reveal.value : "•".repeat(Math.min(reveal.value.length, 20))}</code>
          <button type="button" className={s.ghost} onClick={() => setShown(v => !v)}>{shown ? "Hide" : "Show"}</button>
          <button type="button" className={s.ghost} onClick={() => copy(reveal.value)}>Copy</button>
          <button type="button" className={s.ghost} onClick={() => { setShown(false); clearReveal() }}>I have saved it</button>
          <span className={s.fine}>This is the only time it is shown. It is stored nowhere. (Accounts → New password makes another.)</span>
        </div>
      ) : null}

      {run.status === "open" && next ? (
        <div className={s.actions}>
          <button type="button" className={s.button} disabled={busy} onClick={() => act({ action: "from", id: run.id, step: next.id }, `Running from “${next.label}”…`)} data-testid="run-next">
            Run on from “{next.label}”
          </button>
          <span className={s.fine}>It stops by itself at the first step that fails, is still working, needs a person, spends money or tears down.</span>
        </div>
      ) : null}

      {/* Only until the domain is bought: afterwards the registrar rightly says the name is no longer for sale. */}
      {run.kind === "buy" && run.status === "open" && steps.find(x => x.id === "purchase")?.record.status !== "done" ? <Readiness run={run} /> : null}

      <ol className={s.steps}>
        {steps.map((step, i) => (
          <StepCard key={step.id} step={step} index={i} run={run} safety={safety} act={act} busy={Boolean(busy)} />
        ))}
      </ol>

      <EventLog events={view.events} steps={steps} run={run} act={act} busy={Boolean(busy)} />
    </div>
  )
}

/* ── the panels underneath ──────────────────────────────────────────────── */

const Stuck = ({ stuck, onRetry }) => {
  const [msg, setMsg] = React.useState("")
  const total = stuck.customers.length + stuck.orders.length
  const retry = async (body, key) => {
    setMsg(`Working on ${key}…`)
    const r = await api(body)
    setMsg(r.ok ? `${key}: ${r.body.status || "done"}.` : r.body.message || "That did not work.")
    onRetry()
  }
  return (
    <details className={s.panel} open={total > 0} data-testid="stuck">
      <summary>Needs attention ({total})</summary>
      {total === 0 ? <p className={s.fine}>Every paying customer's address, and every domain order, is where it should be.</p> : null}
      {stuck.customers.map(c => (
        <div key={c.subdomain} className={s.item}>
          <strong>{c.account || "A customer"}: {c.subdomain}</strong>
          <p>{c.reason} <span className={s.fine}>({c.status} since {when(c.since)})</span></p>
          {c.canRetry ? <button type="button" className={s.ghost} onClick={() => retry({ action: "retry-address", subdomain: c.subdomain }, c.subdomain)}>Make their address now</button> : <p className={s.fine}>{c.why}</p>}
        </div>
      ))}
      {stuck.orders.map(o => (
        <div key={o.id} className={s.item}>
          <strong>Domain order: {o.domain}</strong>
          <p>{o.reason} <span className={s.fine}>(since {when(o.updated_at)})</span></p>
          <button type="button" className={s.ghost} onClick={() => retry({ action: "retry-order", orderId: o.id }, o.domain)}>Carry the order on</button>
        </div>
      ))}
      {msg ? <p className={s.notice}>{msg}</p> : null}
    </details>
  )
}

const Accounts = ({ onChange }) => {
  const [q, setQ] = React.useState("")
  const [rows, setRows] = React.useState(null)
  const [reveal, setReveal] = React.useState(null)
  const [msg, setMsg] = React.useState("")
  const load = React.useCallback(async () => {
    const r = await api({ action: "accounts", q })
    if (r.ok) setRows(r.body.accounts)
    else setMsg(r.body.message || "Could not load the accounts.")
  }, [q])
  React.useEffect(() => {
    load()
  }, [load])
  const make = async plan => {
    const r = await api({ action: "account-create", plan })
    if (r.ok) setReveal(r.body.reveal)
    else setMsg(r.body.message || "Could not make the account.")
    load()
    onChange()
  }
  const change = async (action, id) => {
    if (action === "account-delete" && !window.confirm("Delete this test account?")) return
    const r = await api({ action, id })
    if (r.ok && r.body.reveal) setReveal(r.body.reveal)
    else if (!r.ok) setMsg(r.body.message || "That did not work.")
    load()
    onChange()
  }
  return (
    <details className={s.panel} data-testid="accounts">
      <summary>Accounts</summary>
      <div className={s.actions}>
        <button type="button" className={s.ghost} onClick={() => make("free")}>Make a free test account</button>
        <button type="button" className={s.ghost} onClick={() => make("premium")}>Make a paid test account</button>
        <input className={s.input} value={q} onChange={e => setQ(e.target.value)} placeholder="Search by email" aria-label="Search accounts" />
      </div>
      {reveal ? (
        <p className={s.reveal}><strong>{reveal.label}</strong> <code>{reveal.value}</code> <button type="button" className={s.ghost} onClick={() => copy(reveal.value)}>Copy</button> <button type="button" className={s.ghost} onClick={() => setReveal(null)}>Done</button></p>
      ) : null}
      {msg ? <p className={s.error}>{msg}</p> : null}
      <ul className={s.plain}>
        {(rows || []).map(a => (
          <li key={a.id} className={s.account}>
            <span><strong>{a.email}</strong> · {a.plan} · {a.status}{a.subscribed ? " · subscribed" : ""} <span className={s.badge} data-mode={a.testAccount ? "rehearsal" : "real"}>{a.testAccount ? "test account" : "real customer"}</span></span>
            {a.testAccount ? (
              <span className={s.actions}>
                <button type="button" className={s.ghost} onClick={() => change("account-password", a.id)}>New password</button>
                <button type="button" className={s.ghost} onClick={() => change("account-delete", a.id)}>Delete</button>
              </span>
            ) : <span className={s.fine}>Never changed from here.</span>}
          </li>
        ))}
      </ul>
    </details>
  )
}

const OverseerLog = () => {
  const [lines, setLines] = React.useState(null)
  const [filter, setFilter] = React.useState("")
  const [failures, setFailures] = React.useState(false)
  const [msg, setMsg] = React.useState("")
  const pull = async () => {
    const r = await api({ action: "logs", limit: 80, filter, ...(failures ? { ok: false } : {}) })
    if (r.ok) setLines(r.body.lines)
    else setMsg(r.body.message || "Could not pull the log.")
  }
  return (
    <details className={s.panel} data-testid="overseer">
      <summary>Overseer log: everything anyone did on the site</summary>
      <div className={s.actions}>
        <input className={s.input} value={filter} onChange={e => setFilter(e.target.value)} placeholder="Starts with (for example admin.pipeline or payment)" aria-label="Filter the log" />
        <label className={s.check}><input type="checkbox" checked={failures} onChange={e => setFailures(e.target.checked)} /> failures only</label>
        <button type="button" className={s.ghost} onClick={pull}>Pull the log</button>
        <a href="/admin/logs/">Open the full log page</a>
      </div>
      {msg ? <p className={s.error}>{msg}</p> : null}
      {lines ? (
        <ol className={s.events}>
          {lines.length === 0 ? <li className={s.fine}>Nothing matches.</li> : null}
          {lines.map((l, i) => (
            <li key={`${l.at}-${i}`} className={s.event} data-level={l.ok ? "info" : "error"}>
              <span className={s.when}>{when(l.at)}</span>
              <span className={s.lvl}>{l.ok ? "✓" : "✗"}</span>
              <span className={s.msg}><strong>{l.action}</strong>{l.detail ? `: ${l.detail}` : ""}</span>
            </li>
          ))}
        </ol>
      ) : null}
    </details>
  )
}

/* ── trace: what happened to a payment, an account or an address ────────── */

const STATE_WORD = { completed: "Completed", pending: "In progress", failed: "FAILED", stalled: "STALLED", "paid-not-started": "PAID, NOT STARTED", nothing: "Nothing recorded" }
const GOOD = ["completed", "pending", "nothing"]

const Trace = () => {
  const [q, setQ] = React.useState("")
  const [t, setT] = React.useState(null)
  const [activity, setActivity] = React.useState(null)
  const [busy, setBusy] = React.useState("")
  const [msg, setMsg] = React.useState("")

  const loadActivity = React.useCallback(async () => {
    const r = await api({ action: "activity" })
    if (r.ok) setActivity(r.body)
  }, [])
  React.useEffect(() => {
    loadActivity()
  }, [loadActivity])

  const look = async text => {
    const asked = String(text ?? q).trim()
    if (!asked) return
    setQ(asked)
    setBusy("Looking…")
    setMsg("")
    const r = await api({ action: "trace", q: asked })
    setBusy("")
    if (r.ok) setT(r.body)
    else setMsg(r.body.message || "Could not look that up.")
  }
  const run = async (body, label) => {
    setBusy(`${label}…`)
    const r = await api(body)
    setBusy("")
    setMsg(r.ok ? `${label}: ${r.body.state || r.body.status || "done"}${r.body.cid ? ` (this run's id: ${r.body.cid})` : ""}.` : r.body.message || "That did not work.")
    if (t) look(t.q)
    loadActivity()
  }

  return (
    <details className={s.panel} open data-testid="trace">
      <summary>Trace: what happened to a payment, an account or an address</summary>
      <form
        className={s.noteForm}
        onSubmit={e => {
          e.preventDefault()
          look()
        }}
      >
        <input id="pc-trace-q" className={s.input} value={q} onChange={e => setQ(e.target.value)} placeholder="A Stripe event id (evt_…), an account id or email, or an address (acme-roofing or acme.com)" aria-label="Trace" />
        <button type="submit" className={s.button} disabled={Boolean(busy) || !q.trim()}>Trace it</button>
        <button type="button" className={s.ghost} disabled={Boolean(busy)} onClick={() => run({ action: "sweep" }, "Sweep now")} title="Finish every paid address that stopped part-way (the same work the scheduled sweeper does every ten minutes)">Run the sweeper now</button>
      </form>
      {busy ? <p className={s.working} role="status">{busy}</p> : null}
      {msg ? <p className={s.notice} data-testid="trace-message">{msg}</p> : null}

      {t ? (
        <div data-testid="trace-result" data-state={t.verdict?.state}>
          <p className={GOOD.includes(t.verdict?.state) ? s.notice : s.warn} data-testid="trace-verdict">
            <strong>{STATE_WORD[t.verdict?.state] || t.verdict?.state}.</strong> {t.verdict?.why}
          </p>
          {t.account ? (
            <p className={s.fine}>
              Account <code>{t.account.id}</code> · {t.account.email || "no email yet (an anonymous buyer)"} · {t.account.plan} · {t.account.status}
              {t.account.subscription ? ` · subscription ${t.account.subscription}` : ""}
              {t.account.address ? ` · address chosen: ${t.account.address}` : ""}
            </p>
          ) : null}
          {t.staged ? <p className={s.fine}>Saved before checkout: website {t.staged.content ? "yes" : "no"} · drawn page {t.staged.page ? "yes" : "no"}</p> : null}
          {(t.hosting || []).map(h => (
            <div key={h.subdomain} className={s.item}>
              <strong>{h.hostname}</strong> <span className={s.badge} data-mode={GOOD.includes(h.state) ? "rehearsal" : "real"}>{STATE_WORD[h.state] || h.state}</span>
              <p className={s.fine}>
                tried {h.attempts ?? "?"} time(s){h.startedBy ? ` · last started by ${h.startedBy}` : ""}{h.leaseUntil ? ` · held until ${when(h.leaseUntil)}` : ""} · changed {when(h.updatedAt)}
                {h.cid ? <> · id <button type="button" className={s.ghost} onClick={() => look(h.cid)}>{h.cid}</button></> : null}
              </p>
              {h.lastError ? <p className={s.warn}>Last error: {h.lastError}</p> : null}
              <ul className={s.plain}>
                {(h.steps || []).map((st, i) => (
                  <li key={`${st.id}-${i}`}><Mark ok={st.ok} /> {st.label || st.id}{st.detail ? <span className={s.fine}> — {st.detail}</span> : null}</li>
                ))}
              </ul>
            </div>
          ))}
          {(t.orders || []).map(o => (
            <p key={o.id} className={s.fine}>Domain order <strong>{o.domain}</strong>: {o.status}{o.note ? ` · ${o.note}` : ""}</p>
          ))}
          {(t.actions || []).length ? (
            <div className={s.actions}>
              {t.actions.map(a => (
                <button key={a.id} type="button" className={s.ghost} disabled={Boolean(busy)} onClick={() => run(a.id === "finalize" ? { action: "finalize", subdomain: a.subdomain } : { action: "retry-address", subdomain: a.subdomain }, a.label)}>
                  {a.label}
                </button>
              ))}
              <span className={s.fine}>Both are safe to press more than once: nothing is made twice.</span>
            </div>
          ) : null}
          <ol className={s.events} data-testid="trace-timeline">
            {(t.timeline || []).length === 0 ? <li className={s.fine}>No lines.</li> : null}
            {(t.timeline || []).map((e, i) => (
              <li key={`${e.at}-${i}`} className={s.event} data-level={e.ok === false ? "error" : e.ok === true ? "ok" : "info"}>
                <span className={s.when}>{when(e.at)}</span>
                <span className={s.src}>{e.source}</span>
                <span className={s.lvl}>{e.ok === false ? "✗" : e.ok === true ? "✓" : "…"}</span>
                <span className={s.msg}><strong>{e.what}</strong>{e.detail ? `: ${e.detail}` : ""}</span>
              </li>
            ))}
          </ol>
        </div>
      ) : null}

      {activity ? (
        <div data-testid="activity">
          <h3 className={s.h3}>Addresses, latest first</h3>
          {activity.hosting.length === 0 ? <p className={s.fine}>None yet.</p> : null}
          <ul className={s.plain}>
            {activity.hosting.map(h => (
              <li key={h.subdomain}>
                <span className={s.badge} data-mode={GOOD.includes(h.state) ? "rehearsal" : "real"}>{STATE_WORD[h.state] || h.state}</span>{" "}
                <button type="button" className={s.ghost} onClick={() => look(h.subdomain)}>{h.subdomain}</button>
                <span className={s.fine}> tried {h.attempts ?? "?"}× · {when(h.updatedAt)}{h.startedBy ? ` · by ${h.startedBy}` : ""}{h.lastError ? ` · ${h.lastError}` : ""}</span>
              </li>
            ))}
          </ul>
          <h3 className={s.h3}>Stripe events, latest first</h3>
          {activity.events.length === 0 ? <p className={s.fine}>None yet.</p> : null}
          <ul className={s.plain}>
            {activity.events.map(e => (
              <li key={e.id}>
                <Mark ok={e.status === "done" ? true : e.status === "failed" ? false : null} />{" "}
                <button type="button" className={s.ghost} onClick={() => look(e.id)}>{e.id}</button>
                <span className={s.fine}> {e.type} · {e.status}{e.detail ? ` · ${e.detail}` : ""} · {when(e.at)}</span>
              </li>
            ))}
          </ul>
          <h3 className={s.h3}>Failures, latest first</h3>
          {activity.failures.length === 0 ? <p className={s.fine}>None recorded.</p> : null}
          <ul className={s.plain}>
            {activity.failures.map((f, i) => (
              <li key={`${f.at}-${i}`}>
                <Mark ok={false} /> <strong>{f.action}</strong> <span className={s.fine}>{f.detail} · {when(f.at)}</span>
                {f.cid ? <> <button type="button" className={s.ghost} onClick={() => look(f.cid)}>{f.cid}</button></> : null}
              </li>
            ))}
          </ul>
          <button type="button" className={s.ghost} onClick={loadActivity}>Refresh</button>
        </div>
      ) : null}
    </details>
  )
}

const Quicklinks = ({ groups }) => (
  <details className={s.panel} open data-testid="quicklinks">
    <summary>Quicklinks</summary>
    {groups.map(g => (
      <div key={g.group} className={s.linkGroup}>
        <h3 className={s.h3}>{g.group}</h3>
        <ul className={s.plain}>
          {g.links.map(l => (
            <li key={l.url}>
              <a href={l.url} target={l.url.startsWith("/") ? undefined : "_blank"} rel="noreferrer">{l.label}{l.url.startsWith("/") ? "" : " ↗"}</a>
              {l.note ? <span className={s.fine}> — {l.note}</span> : null}
            </li>
          ))}
        </ul>
      </div>
    ))}
  </details>
)

/* ── the console ────────────────────────────────────────────────────────── */

const describe = result => {
  if (!result) return ""
  if (result.refused) return result.refused
  if (result.ran) return `${result.ran.length ? `Ran: ${result.ran.join(", ")}. ` : "Nothing needed running. "}${result.why}`
  if (result.outcome) return result.outcome.detail
  if (result.ok === true) return "Done."
  return ""
}

const PipelineConsole = () => {
  const [overview, setOverview] = React.useState(null)
  const [view, setView] = React.useState(null)
  const [busy, setBusy] = React.useState("")
  const [problem, setProblem] = React.useState("")
  const [notice, setNotice] = React.useState("")
  const [reveal, setReveal] = React.useState(null)
  const [testAccounts, setTestAccounts] = React.useState([])
  const [loading, setLoading] = React.useState(true)
  const viewRef = React.useRef(null)
  viewRef.current = view

  const refreshOverview = React.useCallback(async () => {
    const r = await api({ action: "overview" })
    setLoading(false)
    if (!r.ok) {
      setProblem(r.status === 403 ? "This account is not an administrator." : r.body.message || `Could not load the console (HTTP ${r.status}).`)
      return
    }
    setProblem("")
    setOverview(r.body)
  }, [])

  const loadAccounts = React.useCallback(async () => {
    const r = await api({ action: "accounts" })
    if (r.ok) setTestAccounts(r.body.accounts.filter(a => a.testAccount))
  }, [])

  const open = React.useCallback(async id => {
    setBusy("Looking at the real services…")
    setNotice("")
    setReveal(null)
    const r = await api({ action: "get", id })
    setBusy("")
    if (!r.ok) return setProblem(r.body.message || "Could not open that run.")
    setProblem("")
    setView(r.body)
  }, [])

  React.useEffect(() => {
    refreshOverview()
    loadAccounts()
    // Back from Stripe: /admin/pipeline/?run=<id>&paid=1
    const q = typeof window !== "undefined" ? new URLSearchParams(window.location.search) : null
    const id = q?.get("run")
    if (id) {
      open(id)
      if (q.get("paid") === "1") setNotice("Back from Stripe. If the payment went through, the webhook has recorded it: look at the “The customer pays” step.")
      if (q.get("paid") === "0") setNotice("You left Stripe without paying. Nothing was charged.")
    }
  }, [refreshOverview, loadAccounts, open])

  /* Every action that changes something goes through here. While it works, the log is asked for every couple of seconds so the person
     watches the steps happen instead of a spinner. */
  const act = React.useCallback(
    async (body, label) => {
      const id = body.id || viewRef.current?.run.id
      setBusy(label || "Working…")
      setProblem("")
      setNotice("")
      let timer = null
      if (id && body.action !== "note") {
        timer = setInterval(async () => {
          const r = await api({ action: "events", id })
          if (r.ok && viewRef.current) setView(v => (v ? { ...v, events: r.body.events } : v))
        }, 2500)
      }
      const r = await api(body)
      if (timer) clearInterval(timer)
      setBusy("")
      if (!r.ok) return setProblem(r.body.message || `That did not work (HTTP ${r.status}).`)
      setView(r.body)
      if (r.body.reveal) setReveal(r.body.reveal)
      setNotice(describe(r.body.result))
      refreshOverview()
      loadAccounts()
    },
    [refreshOverview, loadAccounts]
  )

  const create = async input => {
    setBusy("Starting the run…")
    setProblem("")
    const r = await api({ action: "create", ...input, accountId: input.accountId || undefined })
    setBusy("")
    if (!r.ok) return setProblem(r.body.message || "That run could not be started.")
    setView(r.body)
    setReveal(null)
    setNotice("")
    refreshOverview()
  }

  if (loading) return <p className={s.fine}>Opening the console…</p>
  if (!overview) return <p className={s.error} role="alert">{problem || "The console could not be loaded."}</p>

  return (
    <div className={s.wrap} data-testid="console">
      <SafetyBar safety={overview.safety} />
      {problem && !view ? <p className={s.error} role="alert">{problem}</p> : null}

      <div className={s.layout}>
        <aside className={s.side}>
          <NewRun kinds={overview.kinds} safety={overview.safety} testAccounts={testAccounts} onCreate={create} busy={Boolean(busy)} />
          <section className={s.runs} data-testid="runs">
            <h2 className={s.h2}>Runs</h2>
            {overview.runs.length === 0 ? <p className={s.fine}>No runs yet. Start one above.</p> : null}
            <ul className={s.plain}>
              {overview.runs.map(r => (
                <li key={r.id}>
                  <button type="button" className={s.runItem} data-on={view?.run.id === r.id ? "yes" : undefined} data-testid={`run-${r.id}`} onClick={() => open(r.id)}>
                    <strong>{r.kindLabel}: {r.target}</strong>
                    <span className={s.fine}>
                      {r.done} of {r.total} steps · {r.mode === "real" ? "REAL" : "rehearsal"} · {r.status === "open" ? "open" : r.status === "finished" ? "torn down" : "abandoned"}
                      {r.stalled ? " · STALLED" : r.failed ? " · a step failed" : ""}
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </section>
        </aside>

        <main className={s.main}>
          {view ? (
            <RunView view={view} safety={overview.safety} act={act} busy={busy} reveal={reveal} clearReveal={() => setReveal(null)} notice={notice} problem={problem} refresh={() => open(view.run.id)} />
          ) : (
            <div className={s.empty}>
              <h2 className={s.h2}>Pick a run, or start one</h2>
              <p>Work from the cheapest test to the most costly:</p>
              <ol className={s.plain}>
                {overview.kinds.map(k => (
                  <li key={k.id}><strong>{k.label}.</strong> {k.summary}</li>
                ))}
              </ol>
            </div>
          )}
        </main>
      </div>

      <Stuck stuck={overview.stuck} onRetry={refreshOverview} />
      <Trace />
      <Accounts onChange={loadAccounts} />
      <OverseerLog />
      <Quicklinks groups={overview.quicklinks} />
    </div>
  )
}

export default PipelineConsole
